import{_ as a,o as t,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const g=JSON.parse('{"title":"04 · User-Facing Features","description":"","frontmatter":{},"headers":[],"relativePath":"reference/04-user-facing-features.md","filePath":"reference/04-user-facing-features.md","lastUpdated":1788532705000}'),s={name:"reference/04-user-facing-features.md"};function n(d,e,i,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="_04-·-user-facing-features" tabindex="-1">04 · User-Facing Features <a class="header-anchor" href="#_04-·-user-facing-features" aria-label="Permalink to &quot;04 · User-Facing Features&quot;">​</a></h1><p>Three surfaces, all built from the same engine output:</p><ol><li><strong>MCP server</strong> — 17 tools (<code>mcp-server-panchangam</code> on PyPI)</li><li><strong>ICS calendar feeds</strong> — 22 cities × 3 systems, on GitHub Pages</li><li><strong>Landing page</strong> — <code>panchangam.astrochaganti.com</code></li></ol><hr><h2 id="_1-mcp-server-—-17-tools" tabindex="-1">1. MCP server — 17 tools <a class="header-anchor" href="#_1-mcp-server-—-17-tools" aria-label="Permalink to &quot;1. MCP server — 17 tools&quot;">​</a></h2><p>FastMCP server (<a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/telugu_panchangam/mcp/server.py" target="_blank" rel="noreferrer"><code>mcp/server.py</code></a>), with decorator-registered tools wrapping logic in <code>mcp/tools.py</code>. Every tool returns a <strong>JSON string</strong>; failures return <code>{&quot;error&quot;: &quot;…&quot;}</code>.</p><p><strong>Location resolution</strong> (<code>mcp/location.py</code>): a free-text <code>city</code> resolves first against the 22 pre-configured <code>CITIES</code> (instant, no network); unknown names fall back to Nominatim/OpenStreetMap geocoding (10 s timeout) with timezone via <code>timezonefinder</code>. You can also pass <code>latitude</code>/<code>longitude</code>/<code>timezone</code> directly to skip lookup entirely.</p><p><strong>Ayanamsa</strong>: <code>get_panchangam</code>, <code>get_panchangam_range</code>, <code>get_graha_positions</code>, <code>get_gochara</code>, <code>get_rasi_phalalu</code>, <code>get_rashi_ingresses</code>, <code>find_muhurta</code> accept <code>ayanamsa = lahiri | raman | krishnamurti | true_chitrapaksha</code> (default <code>lahiri</code>). SS/Vakya accept it for symmetry but ignore it.</p><h3 id="per-day-single-date" tabindex="-1">Per-day (single date) <a class="header-anchor" href="#per-day-single-date" aria-label="Permalink to &quot;Per-day (single date)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Key params</th></tr></thead><tbody><tr><td><strong><code>get_panchangam</code></strong></td><td>Full day: 5 angas, sky, all windows, Choghadiya, flags, 1.9.0 timing fields</td><td><code>date, city, system, [lat/lon/tz], ayanamsa</code></td></tr><tr><td><strong><code>get_muhurta</code></strong></td><td>Lighter: just the auspicious/inauspicious windows + timing fields (no anga names/sky/Choghadiya)</td><td><code>date, city, system, [lat/lon/tz]</code></td></tr><tr><td><strong><code>get_panchanga_shuddhi</code></strong></td><td>Five-limb purity verdict (Sarva Shuddha → Sarva Ashuddha) + per-limb reason</td><td><code>date, city, system, [lat/lon/tz]</code></td></tr><tr><td><strong><code>get_daily_horas</code></strong></td><td>24 planetary hours (12 day from sunrise + 12 night), weekday-lord sequence</td><td><code>date, city, system, [lat/lon/tz]</code></td></tr><tr><td><strong><code>get_lagna_transitions</code></strong></td><td>Ascendant sign boundaries across the day</td><td><code>date, city, system, [lat/lon/tz]</code></td></tr></tbody></table><h3 id="planning-across-days" tabindex="-1">Planning across days <a class="header-anchor" href="#planning-across-days" aria-label="Permalink to &quot;Planning across days&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Key params</th></tr></thead><tbody><tr><td><strong><code>get_panchangam_range</code></strong></td><td>Compact per-day summary over a range (≤31 days)</td><td><code>start_date, end_date, city, system, ayanamsa</code></td></tr><tr><td><strong><code>get_special_days</code></strong></td><td>Festivals, Ekadashi/Amavasya/Pournami/Pradosham, Sankranti, eclipses in a month</td><td><code>year, month, city, system</code></td></tr><tr><td><strong><code>find_muhurta</code></strong></td><td><strong>Ranked auspicious slots</strong> over coming days, activity-aware, every slot with reasons + tier; hard-avoids doshas</td><td><code>start_date, days(≤14), activity, city, system, janma_nakshatras, janma_rasis, janma_lagnas, chandra_mode, travel_direction, ayanamsa</code></td></tr><tr><td><strong><code>find_tarabalam_days</code></strong></td><td>Days favourable for 1–4 people by birth star (+ optional rasi for Chandrabalam)</td><td><code>janma_nakshatras[1-4], start_date, days(≤60), city, system, janma_rasis, chandra_mode</code></td></tr></tbody></table><h3 id="sky-event-calendars-range" tabindex="-1">Sky-event calendars (range) <a class="header-anchor" href="#sky-event-calendars-range" aria-label="Permalink to &quot;Sky-event calendars (range)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Key params</th></tr></thead><tbody><tr><td><strong><code>get_combustion_calendar</code></strong></td><td>Asta/Udaya (combustion entry/exit) for Mercury/Venus/Mars/Jupiter/Saturn (≤366 days)</td><td><code>start_date, end_date, city, [planets]</code></td></tr><tr><td><strong><code>get_graha_yuddha</code></strong></td><td>Planetary-war periods — winner/loser, timing UTC, min separation (≤366 days)</td><td><code>start_date, end_date, [planets]</code></td></tr><tr><td><strong><code>get_rashi_ingresses</code></strong></td><td>All sign-change events for the classical planets (≤366 days)</td><td><code>start_date, end_date, [planets], ayanamsa</code></td></tr><tr><td><strong><code>get_eclipse_calendar</code></strong></td><td>Solar &amp; lunar eclipses, per-city visibility, Sutak (≤730 days)</td><td><code>start_date, end_date, city</code></td></tr></tbody></table><h3 id="gochara-personal-transits" tabindex="-1">Gochara &amp; personal transits <a class="header-anchor" href="#gochara-personal-transits" aria-label="Permalink to &quot;Gochara &amp; personal transits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Key params</th></tr></thead><tbody><tr><td><strong><code>get_graha_positions</code></strong></td><td>All 9 grahas at sunrise — rasi, nakshatra, pada, retrograde, next-rasi date</td><td><code>date, city, ayanamsa</code></td></tr><tr><td><strong><code>get_gochara</code></strong></td><td>Transit verdicts from a janma rasi — houses, vedha, Sade Sati / Ashtama Shani</td><td><code>date, janma_rasi, city, ayanamsa</code></td></tr><tr><td><strong><code>get_rasi_phalalu</code></strong></td><td>Deterministic daily reading rendered from gochara + chandrabalam + tarabalam</td><td><code>date, janma_rasi, [janma_nakshatra], city, ayanamsa</code></td></tr></tbody></table><h3 id="utility" tabindex="-1">Utility <a class="header-anchor" href="#utility" aria-label="Permalink to &quot;Utility&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><strong><code>list_supported_cities</code></strong></td><td>The 22 pre-configured cities with lat/lon/timezone</td></tr></tbody></table><blockquote><p><strong>17 tools total.</strong> Grouping mirrors the <a href="https://github.com/socraticsurge/telugu-calendar-utilities/blob/master/README_PYPI.md" target="_blank" rel="noreferrer">README_PYPI tool table</a>; this doc adds the parameter and return-shape detail. Full per-field return shapes were mapped during this doc&#39;s generation — see <code>mcp/tools.py</code> for the authoritative serializers.</p></blockquote><hr><h2 id="_2-ics-calendar-feeds" tabindex="-1">2. ICS calendar feeds <a class="header-anchor" href="#_2-ics-calendar-feeds" aria-label="Permalink to &quot;2. ICS calendar feeds&quot;">​</a></h2><p><strong>What:</strong> one all-day event per day, full panchangam in the description. Festival days get 🪔 in the title; other special days (Ekadashi/Amavasya/Pournami/ Pradosham/Sankranti/eclipse) get ⚡.</p><p><strong>Each event&#39;s description</strong> (<code>generators/ics.py</code>): metadata (Samvatsara/Maasam/Paksham/Vaaram, ayanam/rituvu, signs), the five angas with HH:MM(±1) bounds, sky markers, auspicious &amp; inauspicious windows, daytime <strong>and</strong> night Choghadiya, eclipse + Sutak, special yogas, and a specials summary.</p><p><strong>Dense vs variant feeds:</strong></p><ul><li>Dense (default, <code>variant_label=&#39;&#39;</code>): every day, full description.</li><li><strong>Variant feeds</strong> (<code>generators/anga_variants.py</code>): Ekadashi-only, Festivals-only, Moon-Cycles (Pournami+Amavasya) — pure filters that reuse <code>ICSGenerator</code>, so format/metadata never drift. <em>Built but not yet deployed — a deliberate follow-up (see <a href="./06-roadmap-and-backlog">roadmap</a>).</em></li></ul><p><strong>Generation</strong> (<code>generate.py</code>): <code>generate_feeds(out, start, end, systems, cities)</code> precomputes eclipses once, then loops systems × cities × days → <code>{city_slug}-{system}.ics</code>. <strong>22 cities × 3 systems = 66 feeds</strong>, regenerated monthly by GitHub Actions covering ~18 months ahead, served as static files from GitHub Pages (<code>webcal://</code> subscriptions, zero hosting cost).</p><pre class="mermaid">flowchart LR
    CRON[&quot;GitHub Actions&lt;br/&gt;(monthly cron)&quot;] --&gt; GEN[&quot;python -m telugu_panchangam.generate&quot;]
    GEN --&gt;|&quot;22 cities × 3 systems&quot;| ICS[&quot;66 × .ics&quot;]
    ICS --&gt; PAGES[&quot;GitHub Pages&lt;br/&gt;panchangam.astrochaganti.com&quot;]
    PAGES --&gt;|&quot;webcal://&quot;| SUB[&quot;Google / Apple / Outlook&quot;]
</pre><p><strong>Cities:</strong> Telugu heartland (Hyderabad, Vijayawada, Visakhapatnam, Tirupati, Warangal, Guntur, Nizamabad, Rajahmundry, Kurnool, Nellore) · metros (Bengaluru, Chennai, Mumbai, Delhi) · diaspora (Dallas, San Jose, San Francisco, Edison, New York, London, Sydney, Dubai).</p><p><strong>Systems:</strong> Drik Ganita (modern apps) · Surya Siddhanta (classical tradition) · Vakya (Telugu/Tamil printed panchangams).</p><hr><h2 id="_3-landing-page" tabindex="-1">3. Landing page <a class="header-anchor" href="#_3-landing-page" aria-label="Permalink to &quot;3. Landing page&quot;">​</a></h2><p>The Vite/TypeScript application under <code>src/</code>, built by <code>deploy-landing.yml</code> and served at <code>panchangam.astrochaganti.com</code> (the <code>CNAME</code> is load-bearing — never drop it). Beyond letting devotees pick a city/system and copy a <code>webcal://</code> URL, it&#39;s a daily toolkit:</p><ul><li><strong>Today&#39;s Panchangam</strong> — any date, any city.</li><li><strong>Tarabalam · Muhurtam</strong> — good days &amp; ranked time slots for up to four people by birth star, with Chandrabalam. Typed scorer modules consume the generated Python activity contract; runtime <code>lagna.json</code> / <code>gochara.json</code> sidecars supply slot-time data. The per-city Lagna sidecar also carries Guru/Shukra combustion flags, allowing browser Muhurtam searches to enforce the same Maudhya exclusions declared by the Python activity profile. If those flags are absent, affected browser searches fail closed instead of returning unscreened dates. Travel, Gruhapravesha, Seemantha and Surgery name a primary participant for source-specific local checks. Drik activities with one of 27 deterministic chart predicates receive a privacy-minimal DashaFlow candidate-time planetary-position post-screen. The browser uses its validated local Drik/Lahiri Lagna at each sampled minute to recompute Whole Sign houses; a partial five-minute transition guard is retained for review instead of receiving a false pass or rejection. Preferences are tie-breaks, not score inflation. Gold / jewelry purchase adds four event-specific <code>qualify</code> predicates: a conclusive miss keeps the slot and raw score but caps its rating at Good, while unresolved sample or transition evidence stays review-gated. This does not assess the general election-chart baseline, and qualitative clauses remain explicit. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>. This post-screen is independently disabled in public builds unless <code>VITE_ELECTION_CHART_API_ENABLED</code> is the exact string <code>true</code>; an absent flag enables it only on loopback. Disabled searches keep the Panchangam shortlist, cap any <code>Excellent</code> label at <code>Good</code>, require review, and make no chart request. Public requests can use only the canonical Astro Chaganti HTTPS guest gateway; browser activation does not activate the gateway or sidecar.</li><li><strong>Gochara + Rasi Phalalu</strong> — South Indian chart, transit verdicts, computed daily reading.</li></ul><p>Everything is shareable to WhatsApp.</p><h3 id="guest-profiles-and-local-data" tabindex="-1">Guest profiles and local data <a class="header-anchor" href="#guest-profiles-and-local-data" aria-label="Permalink to &quot;Guest profiles and local data&quot;">​</a></h3><p>Guests can save up to <strong>four profiles</strong> for reuse in Daily Horoscope and Muhurtam. Manual entry is always available. On localhost, or in a public build that explicitly enables the remote calculation capability, the default flow accepts name, exact date/time of birth, and a selected birthplace. After an explicit calculation, it shows Nakshatra, Padam, Janma Rashi, Lagna, a South Indian D1 chart, an accessible graha table, and the calculation method before anything is saved.</p><p>The Profiles destination supports create, edit, delete, and clear-all actions. Recalculation and editing of a calculated profile are available only while the birth-calculation capability is active. When it is inactive, an already-saved calculated profile remains viewable and usable and is never converted into a manual profile. A saved profile can contain:</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose and readiness</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Required display label for recognizing the person.</td></tr><tr><td><strong>Date, time, and selected birthplace</strong></td><td>Used by calculated profiles to reproduce the birth instant and location-dependent Lagna.</td></tr><tr><td><strong>Nakshatra</strong></td><td>Calculated from the sidereal Moon longitude, or supplied manually; required for Muhurtam and for deriving the Daily Horoscope&#39;s Janma Rashi.</td></tr><tr><td><strong>Padam</strong></td><td>Optional for Muhurtam; needed for Daily Horoscope only when the selected Nakshatra spans two Rashis.</td></tr><tr><td><strong>Janma Rashi</strong></td><td>Calculated from Chandra with the disclosed sidereal convention.</td></tr><tr><td><strong>Lagna</strong></td><td>Calculated from the exact birth instant and selected coordinates; it remains optional in a manual profile.</td></tr><tr><td><strong>D1 chart and provenance</strong></td><td>Nine graha positions, Whole Sign houses, contract version, engine version, Lahiri ayanamsha, and the actual reported ephemeris.</td></tr></tbody></table><p>A profile is <strong>Muhurtam-ready</strong> once it has a Nakshatra. It is <strong>Daily Horoscope-ready</strong> once its Janma Rashi can be derived from the Nakshatra, with Padam supplied for a Nakshatra that crosses a Rashi boundary. Contextual create and edit actions return to the originating journey; a one-off Muhurtam person can remain limited to that search instead of becoming a saved profile.</p><p>Profiles are stored only in this browser&#39;s origin-scoped <code>localStorage</code>. The name never leaves the browser. Place search sends the submitted city/town text; calculation sends the date, time, selected coordinates, and IANA timezone to a stateless Astro Chaganti gateway and authenticated DashaFlow sidecar. See the <a href="./53-birth-profile-calculation">full calculation and privacy contract</a>.</p><p>Public builds fail closed by default. <code>VITE_BIRTH_PROFILE_API_ENABLED=true</code> is the only public opt-in, and <code>true</code> must be the exact, case-sensitive string; whitespace, alternate casing, empty and malformed values disable calculation. An absent flag enables calculation only on <code>localhost</code>, <code>127.0.0.1</code>, or <code>[::1]</code>. Public pages always route through the canonical <code>https://astrochaganti.com/api/guest</code> HTTPS gateway and ignore loopback or arbitrary base overrides. The client flag controls presentation and requests; independent server-side activation remains mandatory and blocked pending the licensing and place-provider decisions tracked in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/231" target="_blank" rel="noreferrer">#231</a> and <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/233" target="_blank" rel="noreferrer">#233</a>.</p><p>Anyone using the same browser profile and site origin can see the saved data. It is isolated from other browsers, devices, domains, protocols, and ports (including a local test server running on a different port). Clearing site data or deleting a profile is permanent, and private-browsing storage may disappear when the private session ends. There is no account, cloud sync, cross-device transfer, or recovery.</p><p>GoatCounter may receive fixed, content-free interface events. Analytics must never receive profile names, birth details, coordinates, Nakshatra, Padam, Lagna, chart data, profile IDs, or stored journey selections.</p><blockquote><p>MCP remains the complete computational interface. The website intentionally presents a curated devotee-facing subset; its declared activity catalogue and generated rule contract are protected by parity tests.</p></blockquote>`,44)])])}const p=a(s,[["render",n]]);export{g as __pageData,p as default};
